-- climate for one facility ({{ID}}), generated by scripts/build-explorer-sql.py.
-- Percentiles need every facility, so a live run costs as much as the all-facilities query;
-- the app reads precomputed rows.
SELECT * EXCLUDE (id) FROM (
WITH
-- Units: one row per data center from the chosen source ({{SOURCE}}), with its H3 res-8
-- cells. Shared by every theme: scripts/build-explorer-sql.py puts this in front of each
-- theme body, so every pillar ranks exactly the same facilities.
--   fac   one row per facility: id (_cng_fid of the source's own file, which is also the
--         boundary tiles' id), name, status class, lat, lon.
--   site  the res-8 cell holding the facility point (about 0.7 km²), for site variables.
--   ring  the res-8 cells whose centre lies within {{RADIUS}} miles of the facility.
-- FracTracker statuses are grouped into four classes and filtered by {{STATUS}}. Epoch is
-- filtered to US sites. PNNL projected sites are one growth scenario ({{GROWTH}}) at market
-- gravity weight 50, located by the centroid of their footprint.
fac0 AS (
  SELECT _cng_fid AS id, facility_name AS name, lat, long AS lon,
         CASE WHEN status IN ('Proposed', 'Pre-proposal') THEN 'proposed'
              WHEN status = 'Approved/Permitted/Under construction' THEN 'approved'
              WHEN status IN ('Operating', 'Expanding') THEN 'operating'
              ELSE 'halted' END AS status_class
  FROM read_parquet('s3://public-datacenters/fractracker/data-centers.parquet')
  WHERE '{{SOURCE}}' = 'fractracker' AND lat IS NOT NULL AND long IS NOT NULL
  UNION ALL
  SELECT _cng_fid, name, latitude, longitude, CASE WHEN operational THEN 'operating' ELSE 'approved' END
  FROM read_parquet('s3://public-datacenters/epoch/ai-data-centers.parquet')
  WHERE '{{SOURCE}}' = 'epoch' AND country = 'United States' AND latitude IS NOT NULL
  UNION ALL
  SELECT _cng_fid, COALESCE(NULLIF(name, ''), NULLIF(operator, ''), 'Campus ' || id), lat, lon, 'operating'
  FROM read_parquet('s3://public-datacenters/pnnl-im3/atlas-campus.parquet')
  WHERE '{{SOURCE}}' = 'pnnl-atlas'
  UNION ALL
  SELECT _cng_fid, 'Modelled site ' || id, ST_Y(ST_Centroid(geom)), ST_X(ST_Centroid(geom)), 'projected'
  FROM read_parquet('s3://public-datacenters/pnnl-im3/projected.parquet')
  WHERE '{{SOURCE}}' = 'pnnl-projected' AND growth_scenario = '{{GROWTH}}' AND market_gravity_weight = 50
  UNION ALL
  -- National baseline only (scripts/build-national.py; not a choice in the app): about 2,000
  -- res-8 cells of the contiguous US, picked by hash so the sample is the same on every run.
  SELECT DISTINCT h8::BIGINT, 'Sample cell', h3_cell_to_lat(h8), h3_cell_to_lng(h8), 'sample'
  FROM read_parquet('s3://public-census/census-2024/county/hex/h0=*/data_0.parquet')
  WHERE '{{SOURCE}}' = 'us-sample' AND hash(h8) % 5000 = 0 AND STATEFP NOT IN ('02', '15') AND STATEFP < '60'
),
fac AS MATERIALIZED (
  SELECT *, h3_latlng_to_cell(lat, lon, 8)::UBIGINT AS h8
  FROM fac0
  WHERE '{{SOURCE}}' <> 'fractracker' OR 'all' IN ({{STATUS}}) OR status_class IN ({{STATUS}})
),
site AS MATERIALIZED (
  SELECT id, h8, h3_cell_to_parent(h8, 0)::BIGINT AS h0, h3_cell_area(h8, 'km^2') AS a FROM fac
),
ring AS MATERIALIZED (
  SELECT id, h8, h3_cell_to_parent(h8, 0)::BIGINT AS h0, h3_cell_area(h8, 'km^2') AS a
  FROM (
    SELECT f.id, f.lat, f.lon,
           UNNEST(h3_grid_disk(f.h8, CAST(CEIL({{RADIUS}} * 1.609344 / 0.69) AS INTEGER) + 1))::UBIGINT AS h8
    FROM fac f
  )
  WHERE 2 * 6371.0088 * ASIN(SQRT(
          POWER(SIN(RADIANS(h3_cell_to_lat(h8) - lat) / 2), 2)
          + COS(RADIANS(lat)) * COS(RADIANS(h3_cell_to_lat(h8)))
            * POWER(SIN(RADIANS(h3_cell_to_lng(h8) - lon) / 2), 2)))
        <= {{RADIUS}} * 1.609344
),
-- Climate footprint: the facility's reported size and power, and the carbon stored on its site.
-- FracTracker text fields are read with TRY_CAST, so an entry such as "300+" counts as missing.
attr AS (
  SELECT _cng_fid AS id,
         NULLIF(TRY_CAST(mw AS DOUBLE), 0) AS mw,
         NULLIF(TRY_CAST(replace(facility_size_sqft, ',', '') AS DOUBLE), 0) AS sqft,
         CASE WHEN regexp_matches(lower(COALESCE(power_source, '') || ' ' || COALESCE(dedicated_power_plant, '')),
                                  'gas|coal|oil|diesel|turbine|fracked|fossil') THEN 1 ELSE 0 END AS fossil,
         NULL::DOUBLE AS cool_mwh
  FROM read_parquet('s3://public-datacenters/fractracker/data-centers.parquet') WHERE '{{SOURCE}}' = 'fractracker'
  UNION ALL
  SELECT _cng_fid, NULLIF(current_power_mw, 0), NULL, NULL, NULL
  FROM read_parquet('s3://public-datacenters/epoch/ai-data-centers.parquet') WHERE '{{SOURCE}}' = 'epoch'
  UNION ALL
  SELECT _cng_fid, NULL, NULLIF(sqft, 0), NULL, NULL
  FROM read_parquet('s3://public-datacenters/pnnl-im3/atlas-campus.parquet') WHERE '{{SOURCE}}' = 'pnnl-atlas'
  UNION ALL
  SELECT _cng_fid, data_center_it_power_mw, campus_size_square_ft, NULL, cooling_energy_demand_mwh
  FROM read_parquet('s3://public-datacenters/pnnl-im3/projected.parquet') WHERE '{{SOURCE}}' = 'pnnl-projected'
),
-- Conservation International vulnerable carbon 2024, total Mg C in the facility's res-8 cell
carbon AS (
  SELECT s.id, SUM(c.carbon) AS mg
  FROM site s
  JOIN read_parquet('s3://public-carbon/vulnerable-carbon-2024/hex/h0=*/data_0.parquet') c
    ON c.h0 = s.h0 AND c.h8 = s.h8
  WHERE NOT isnan(c.carbon)
  GROUP BY s.id
),
agg AS (
  SELECT f.id, a.mw, a.sqft, a.fossil, a.cool_mwh, COALESCE(c.mg, 0) AS carbon
  FROM fac f LEFT JOIN attr a USING (id) LEFT JOIN carbon c USING (id)
),
vals AS (
  SELECT id, 'power_mw' AS variable, 'Power capacity' AS label, mw AS value, 'MW' AS unit, 'compact' AS fmt, 'log' AS scale, 1 AS dir FROM agg
  UNION ALL SELECT id, 'floor_area', 'Floor area', sqft, 'sq ft', 'compact', 'log', 1 FROM agg
  UNION ALL SELECT id, 'fossil_power', 'Dedicated fossil power reported', fossil, 'yes = 1', 'int', 'linear', 1 FROM agg
  UNION ALL SELECT id, 'site_carbon', 'Vulnerable carbon in the site cell', carbon, 'Mg C', 'compact', 'linear', 1 FROM agg
  UNION ALL SELECT id, 'cooling_energy', 'Cooling energy demand', cool_mwh, 'MWh per year', 'compact', 'linear', 1 FROM agg
),
-- Score: mid-rank percentile, 0-100, among the facilities in view that have a value. Tied
-- values share the midpoint of their rank range. dir = +1 when a higher value means more
-- likely impact or concern, -1 when a lower value does.
ranked AS (
  SELECT *, CASE WHEN value IS NULL THEN NULL
                 ELSE ROUND(100 * ((RANK() OVER w - 1) + (COUNT(*) OVER w - 1)) / 2.0
                            / NULLIF(COUNT(*) OVER (PARTITION BY variable, value IS NULL) - 1, 0), 1)
            END AS pct
  FROM vals
  WINDOW w AS (PARTITION BY variable, value IS NULL ORDER BY dir * value)
)
-- value is kept to 4 significant figures
SELECT id, variable, label,
       CASE WHEN value IS NULL OR value = 0 THEN value
            ELSE ROUND(value, 3 - CAST(FLOOR(LOG10(ABS(value))) AS INTEGER)) END AS value,
       unit, fmt, scale, dir, pct,
       ROUND(AVG(pct) OVER (PARTITION BY id), 1) AS pillar_score
FROM ranked
ORDER BY id, variable

) WHERE id = {{ID}}
